import json, tempfile, os, numpy as np

# Create synthetic gradient data for 3 conditions
np.random.seed(42)
tmpdir = tempfile.mkdtemp()

conditions = {
    'vanilla_v2': {'has_occ': False},
    'full_occ_ln_v2': {'has_occ': True},
    'detach_ln_v2': {'has_occ': False},
}

for cond, meta in conditions.items():
    data = {'per_layer': {}}
    # DINOv2: 23 blocks
    for i in range(23):
        entry = {
            'action_grad_norm_mean': float(np.random.lognormal(-3, 1)),
            'action_grad_norm_std': float(np.random.uniform(0.001, 0.01)),
        }
        if meta['has_occ']:
            entry['cosine_sim_mean'] = float(np.random.uniform(-0.3, 0.3))
            entry['cosine_sim_std'] = float(np.random.uniform(0.05, 0.15))
            entry['conflict_rate'] = float(np.random.uniform(0.3, 0.5))
        data['per_layer'][f'featurizer.blocks.{i}'] = entry

    # SigLIP: 26 blocks
    for i in range(26):
        entry = {
            'action_grad_norm_mean': float(np.random.lognormal(-2, 0.8)),
            'action_grad_norm_std': float(np.random.uniform(0.001, 0.01)),
        }
        if meta['has_occ']:
            entry['cosine_sim_mean'] = float(np.random.uniform(-0.1, 0.5))
            entry['cosine_sim_std'] = float(np.random.uniform(0.05, 0.15))
            entry['conflict_rate'] = float(np.random.uniform(0.2, 0.4))
        data['per_layer'][f'fused_featurizer.blocks.{i}'] = entry

    fpath = os.path.join(tmpdir, f'{cond}.json')
    with open(fpath, 'w') as f:
        json.dump(data, f)
    print(f'Created {fpath}')

print(f'TMPDIR={tmpdir}')
" 2>&1
